package com.java.labs;

import java.io.IOException;
import java.io.FileReader;
import java.io.FileWriter;

public class Lab01 {
    public static void main(String[] args){
        try {

            FileWriter fw = new FileWriter("LuckyNumber.csv");
            FileReader fr = new FileReader("LuckyNumber.csv");
            int characters;
            for(int i = 1; i <= 500; i++){
                double num = Math.floor(Math.random() * 500); 
                // Math.floor rounds down to the integer lower or equal to the number generated by Math.random
                // Just didn't want long decimals for the output because they're ugly :P
                fw.write(num + "\n");
            };

            fw.close();
            
            while((characters = fr.read()) != -1){
                System.out.print((char) characters);
                // Reads each char from the file and prints them out
            }
            fr.close();
            
        } catch (IOException e) {
            System.out.println("An unexpected error has occured!");
        }
    }
}
